#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int count1 = 0, count2 = 0;
    for (int i = 0; i < n; i++) {
        int t;
        scanf("%d", &t);
        if (t == 1) count1++;
        else if (t == 2) count2++;
    }

    int p, m;
    scanf("%d", &p);
    scanf("%d", &m);

    if (count1 <= p && count2 <= m) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    return 0;
}
```

